// Monta o resumo do cliente para o painel (cliente, documentos e mensagens não lidas)
public async Task<Retorno<ResumoClienteDto>> ObterResumo(string clienteId)
{
    if (string.IsNullOrWhiteSpace(clienteId))
        return Retorno<ResumoClienteDto>.Erro("Id do cliente é obrigatório");

    var tarefaCliente = _clienteRepository.GetById(clienteId);              // ~100 ms
    var tarefaDocumentos = _documentoRepository.ListarPorCliente(clienteId); // ~300 ms
    var tarefaNaoLidas = _chatRepository.ContarNaoLidas(clienteId);          // ~200 ms

    await Task.WhenAll(tarefaCliente, tarefaDocumentos, tarefaNaoLidas);

    var cliente = tarefaCliente.Result;
    if (cliente == null)
        return Retorno<ResumoClienteDto>.Erro($"Cliente {clienteId} não encontrado");

    var documentos = tarefaDocumentos.Result;

    return Retorno<ResumoClienteDto>.Ok(new ResumoClienteDto
    {
        Nome = cliente.Nome,
        TotalDocumentos = documentos.Count,
        Pendentes = documentos.Count(d => d.Status == "PENDENTE"),
        MensagensNaoLidas = tarefaNaoLidas.Result
    });
}

