export class ChatConversaComponent implements OnInit {
  private destroyRef = inject(DestroyRef);
  mensagens: Mensagem[] = [];
  digitando = false;

  ngOnInit(): void {
    // 1) histórico da conversa (HTTP)
    this.chatService.listarHistorico(this.conversaId)
      .subscribe(lista => this.mensagens = lista);

    // 2) mensagens novas que chegam pelo hub (Subject no serviço)
    this.chatService.novaMensagem$
      .pipe(takeUntilDestroyed(this.destroyRef))
      .subscribe(msg => this.mensagens.push(msg));

    // 3) 'fulano está digitando...' (BehaviorSubject<boolean> no serviço)
    this.chatService.digitando$
      .subscribe(valor => this.digitando = valor);

    // 4) a cada 30 s marca a conversa como lida (HTTP dentro)
    interval(30000)
      .subscribe(() => this.chatService.marcarComoLida(this.conversaId).subscribe());
  }
}

