  cliente: this.clienteService.obter(id),
  documentos: this.documentoService.listar(id)
}).pipe(
  map(({ cliente, documentos }) => ({
    nome: cliente?.nomeSocial ?? cliente?.nome ?? 'Sem nome',
    pendentes: documentos.filter(d => d.status === 'PENDENTE').length,
    temVencido: documentos.some(d => new Date(d.vencimento) < new Date())
  }))
);

